using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace ValkyrieRepair {
public class MainForm : Form {
    readonly Color Back=Color.FromArgb(22,22,22), Panel=Color.FromArgb(34,34,34), Line=Color.FromArgb(82,82,82), Ink=Color.WhiteSmoke, Muted=Color.Silver, Good=Color.White, Warn=Color.Gold, Bad=Color.FromArgb(255,84,84);
    PictureBox banner=new PictureBox(); ComboBox installs=new ComboBox();
    Button add=new Button(), find=new Button(), scan=new Button(), apply=new Button(), undo=new Button(), export=new Button();
    Label status=new Label(), summary=new Label(), repairLabel=new Label(), resultLabel=new Label(); PictureBox eagleLogo=new PictureBox(), ssmpLogo=new PictureBox(), sprpLogo=new PictureBox();
    ListView repairs=new ListView(), results=new ListView(); RichTextBox explanation=new RichTextBox();
    SplitContainer lower=new SplitContainer(); CancellationTokenSource work; ScanResult current; string selectedRoot; bool selecting;

    public MainForm(){Text="Valkyrie Repair 1.2";Icon=LoadIcon("repair-icon.ico");MinimumSize=new Size(900,760);Size=new Size(1040,860);BackColor=Back;ForeColor=Ink;Font=new Font("Segoe UI",9F);BuildUi();Shown+=delegate{BeginDiscovery(null);};}

    void BuildUi(){
        explanation.DetectUrls=true;explanation.LinkClicked+=(sender,e)=>OpenUrl(e.LinkText);
        var hero=new Panel{Dock=DockStyle.Top,Height=267,BackColor=Color.Black};banner.Dock=DockStyle.Fill;banner.SizeMode=PictureBoxSizeMode.Zoom;banner.Image=LoadImage("banner-thinking.png");hero.Controls.Add(banner);
        var toolbar=new TableLayoutPanel{Dock=DockStyle.Top,Height=68,ColumnCount=6,RowCount=2,Padding=new Padding(10,7,10,5),BackColor=Back};
        toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,42));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,42));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,42));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,78));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,78));
        installs.Dock=DockStyle.Fill;installs.DropDownStyle=ComboBoxStyle.DropDownList;installs.SelectedIndexChanged+=delegate{SelectionChanged();};
        Small(add,"+","Add a game folder");add.Click+=delegate{AddFolder();};Small(find,"⌕","Find game installations again");find.Click+=delegate{BeginDiscovery(null);};Small(scan,"↻","Scan selected game again");scan.Click+=delegate{BeginScan();};Small(apply,"Apply checked","Apply checked repairs");apply.Click+=delegate{ApplyChecked();};Small(undo,"Undo last","Undo the latest repair");undo.Click+=delegate{UndoLast();};Small(export,"Report","Save a text report");export.Click+=delegate{ExportReport();};
        toolbar.Controls.Add(installs,0,0);toolbar.Controls.Add(add,1,0);toolbar.Controls.Add(find,2,0);toolbar.Controls.Add(scan,3,0);toolbar.Controls.Add(undo,4,0);toolbar.Controls.Add(export,5,0);
        summary.Dock=DockStyle.Fill;summary.ForeColor=Muted;toolbar.SetColumnSpan(summary,6);toolbar.Controls.Add(summary,0,1);
        var body=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=4,ColumnCount=1,Padding=new Padding(10,0,10,8),BackColor=Back};body.RowStyles.Add(new RowStyle(SizeType.Absolute,25));body.RowStyles.Add(new RowStyle(SizeType.Percent,43));body.RowStyles.Add(new RowStyle(SizeType.Absolute,25));body.RowStyles.Add(new RowStyle(SizeType.Percent,57));
        repairLabel.Text="REPAIRS YOU CAN CHOOSE — tick a row, then click Apply checked";repairLabel.Dock=DockStyle.Fill;repairLabel.ForeColor=Ink;repairLabel.Font=new Font(Font,FontStyle.Bold);repairLabel.Padding=new Padding(4,5,0,0);
        SetupList(repairs,true);repairs.Columns.Add("Repair",360);repairs.Columns.Add("Why it was suggested",500);repairs.Columns.Add("Choice",100);repairs.SelectedIndexChanged+=delegate{ShowRepair();};
        resultLabel.Text="FULL SCAN RESULTS — information below never changes files";resultLabel.Dock=DockStyle.Fill;resultLabel.ForeColor=Ink;resultLabel.Font=new Font(Font,FontStyle.Bold);resultLabel.Padding=new Padding(4,5,0,0);
        lower.Dock=DockStyle.Fill;lower.Orientation=Orientation.Vertical;lower.SplitterDistance=610;SetupList(results,false);results.Columns.Add("Result",85);results.Columns.Add("Check",300);results.Columns.Add("What it means",520);results.SelectedIndexChanged+=delegate{ShowResult();};
        explanation.Multiline=true;explanation.ReadOnly=true;explanation.ScrollBars=RichTextBoxScrollBars.Vertical;explanation.Dock=DockStyle.Fill;explanation.BackColor=Panel;explanation.ForeColor=Ink;explanation.BorderStyle=BorderStyle.FixedSingle;explanation.Font=new Font("Consolas",9F);lower.Panel1.Controls.Add(results);lower.Panel2.Padding=new Padding(8,0,0,0);lower.Panel2.Controls.Add(explanation);
        body.Controls.Add(repairLabel,0,0);body.Controls.Add(repairs,0,1);body.Controls.Add(resultLabel,0,2);body.Controls.Add(lower,0,3);
        var actionBar=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=46,ColumnCount=3,Padding=new Padding(8,6,8,6),BackColor=Back};actionBar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));actionBar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,220));actionBar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));apply.Dock=DockStyle.Fill;apply.Font=new Font(Font,FontStyle.Bold);actionBar.Controls.Add(apply,1,0);
        var footer=new Panel{Dock=DockStyle.Bottom,Height=38,BackColor=Color.FromArgb(15,15,15),Padding=new Padding(10,3,10,3)};var footerText=new Label{Text="Valkyrie © 2026  •  Repair Tool     Supports:",Dock=DockStyle.Left,Width=250,TextAlign=ContentAlignment.MiddleLeft,ForeColor=Muted};SetupLogo(eagleLogo,"doctor-eagle.bmp",38);SetupLogo(ssmpLogo,"doctor-ssmp.bmp",44);SetupLogo(sprpLogo,"sprp-logo.png",98);eagleLogo.Cursor=Cursors.Hand;eagleLogo.Click+=delegate{OpenUrl("https://www.projecteaglemod.games/");};sprpLogo.Cursor=Cursors.Hand;sprpLogo.Click+=delegate{OpenUrl("https://sp-rp.com/");};footer.Controls.Add(sprpLogo);footer.Controls.Add(ssmpLogo);footer.Controls.Add(eagleLogo);footer.Controls.Add(footerText);
        status.Dock=DockStyle.Bottom;status.Height=26;status.Padding=new Padding(10,4,10,3);status.ForeColor=Muted;status.BackColor=Back;
        Controls.Add(body);Controls.Add(actionBar);Controls.Add(status);Controls.Add(footer);Controls.Add(toolbar);Controls.Add(hero);SetStatus("Finding your game automatically…");
    }

    void Small(Button b,string text,string tip){b.Text=text;b.Dock=DockStyle.Fill;b.Margin=new Padding(3,0,3,0);b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Line;b.BackColor=Panel;b.ForeColor=Ink;new ToolTip().SetToolTip(b,tip);}
    void SetupLogo(PictureBox box,string resource,int width){box.Dock=DockStyle.Left;box.Width=width;box.Padding=new Padding(3,0,3,0);box.SizeMode=PictureBoxSizeMode.Zoom;box.Image=LoadImage(resource);}
    void OpenUrl(string url){try{Process.Start(url);}catch(Exception e){MessageBox.Show(this,e.Message,"Could not open link");}}
    void SetupList(ListView v,bool boxes){v.Dock=DockStyle.Fill;v.View=View.Details;v.FullRowSelect=true;v.HideSelection=false;v.MultiSelect=false;v.CheckBoxes=boxes;v.BackColor=Panel;v.ForeColor=Ink;v.BorderStyle=BorderStyle.FixedSingle;v.HeaderStyle=ColumnHeaderStyle.Nonclickable;}
    Image LoadImage(string name){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(s==null)return null;using(var source=Image.FromStream(s))return new Bitmap(source);}}
    Icon LoadIcon(string name){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(s==null)return null;using(var source=new Icon(s))return new Icon(source,32,32);}}
    void ShowBanner(string name){var next=LoadImage(name);if(next!=null){var old=banner.Image;banner.Image=next;if(old!=null)old.Dispose();}}

    void BeginDiscovery(string folder){RunWork("Finding GTA San Andreas and Project Eagle installations…",token=>{var found=Discovery.Search(folder,token,s=>BeginInvoke((Action)(()=>SetStatus(s))));BeginInvoke((Action)(()=>MergeInstalls(found)));});}
    void MergeInstalls(IEnumerable<Installation> found){string keep=selectedRoot;var all=installs.Items.Cast<Installation>().Concat(found).GroupBy(i=>i.Root,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).OrderBy(i=>i.Root).ToList();selecting=true;installs.Items.Clear();foreach(var i in all)installs.Items.Add(i);int index=all.FindIndex(i=>String.Equals(i.Root,keep,StringComparison.OrdinalIgnoreCase));if(all.Count>0)installs.SelectedIndex=index>=0?index:0;selecting=false;if(all.Count==0){summary.Text="No game found. Click + to choose its folder.";SetStatus("Waiting for a game folder.");return;}summary.Text=all.Count==1?"Game found. Scanning automatically…":all.Count+" games found. Choose one; each selection scans automatically.";SelectionChanged();}
    void SelectionChanged(){if(selecting)return;var selected=installs.SelectedItem as Installation;selectedRoot=selected==null?null:selected.Root;current=null;repairs.Items.Clear();results.Items.Clear();explanation.Clear();if(selectedRoot!=null)BeginScan();}
    void AddFolder(){using(var d=new FolderBrowserDialog{Description="Choose the folder containing gta_sa.exe or gta_pe.exe"})if(d.ShowDialog(this)==DialogResult.OK){if(!Filesystem.IsInstall(d.SelectedPath)){MessageBox.Show(this,"That is not the game folder. Choose the folder that directly contains gta_sa.exe, gta-sa.exe, or gta_pe.exe.","Game not found");return;}MergeInstalls(new[]{new Installation{Root=Filesystem.Normalize(d.SelectedPath)}});}}
    void BeginScan(){if(String.IsNullOrEmpty(selectedRoot))return;string root=selectedRoot;RunWork("Scanning "+root+"…",token=>{var report=Scanner.Scan(root,token);BeginInvoke((Action)(()=>Display(report)));});}

    void Display(ScanResult report){current=report;repairs.Items.Clear();results.Items.Clear();explanation.Clear();foreach(var f in report.Findings){if(f.Repairable){var row=new ListViewItem(new[]{f.Title,Short(f.Evidence),"Not checked"});row.Tag=f;row.Checked=false;row.ForeColor=f.Title.StartsWith("Optional:")?Warn:Good;repairs.Items.Add(row);}else if(f.Severity=="Checked"||f.Severity=="Information"||f.Severity=="Problem"||!f.Advice.StartsWith("Repair available above:",StringComparison.OrdinalIgnoreCase)){string state=f.Severity=="Checked"?"OK":(f.Severity=="Problem"?"PROBLEM":"INFO");var row=new ListViewItem(new[]{state,f.Title,f.Advice});row.Tag=f;row.ForeColor=state=="OK"?Good:(state=="PROBLEM"?Bad:Muted);results.Items.Add(row);}}
        int fixes=report.Findings.Count(f=>f.Repairable),problems=report.Findings.Count(f=>f.Severity=="Problem"),reviews=report.Findings.Count(f=>!f.Repairable&&(f.Severity=="Review"||f.Severity=="Log evidence"));summary.Text=report.Files+" files · "+fixes+" repairs available · "+problems+" problems · "+reviews+" things to review";ShowBanner(problems>0?"banner-stop.png":(report.Incomplete?"banner-unsure.png":"banner-yay.png"));apply.Enabled=fixes>0;if(repairs.Items.Count>0)repairs.Items[0].Selected=true;else if(results.Items.Count>0)results.Items[0].Selected=true;SetStatus("Scan finished. Nothing was changed.");}
    string Short(string value){value=value??"";return value.Length>140?value.Substring(0,137)+"…":value;}
    void ShowRepair(){if(repairs.SelectedItems.Count==0)return;var f=(Finding)repairs.SelectedItems[0].Tag;explanation.Text="REPAIR\r\n======\r\n"+f.Title+"\r\n\r\nWhy:\r\n"+f.Evidence+"\r\n\r\nWhat it does:\r\n"+f.Advice+"\r\n\r\nThis repair is applied only if you tick it and click Apply checked. An Undo record is created.";}
    void ShowResult(){if(results.SelectedItems.Count==0)return;var f=(Finding)results.SelectedItems[0].Tag;explanation.Text="SCAN RESULT\r\n===========\r\n"+f.Title+"\r\n\r\nWhat Valkyrie found:\r\n"+f.Evidence+"\r\n\r\nWhat to do:\r\n"+f.Advice+"\r\n\r\nThis is information only. It cannot change files.";}
    void ApplyChecked(){if(current==null)return;var chosen=repairs.Items.Cast<ListViewItem>().Where(i=>i.Checked).ToList();if(chosen.Count==0){MessageBox.Show(this,"Tick the repair rows you want first.","Nothing checked");return;}string names=String.Join("\r\n",chosen.Select(i=>"• "+((Finding)i.Tag).Title));if(MessageBox.Show(this,"Apply these repairs?\r\n\r\n"+names+"\r\n\r\nYou can use Undo last afterward.","Confirm repairs",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;var errors=new List<string>();foreach(var row in chosen){try{RepairEngine.Apply(current.Root,(Finding)row.Tag);}catch(Exception e){errors.Add(((Finding)row.Tag).Title+": "+e.Message);}}if(errors.Count>0)MessageBox.Show(this,String.Join("\r\n\r\n",errors),"Some repairs were blocked");BeginScan();}
    void UndoLast(){if(String.IsNullOrEmpty(selectedRoot))return;try{var latest=RepairEngine.History(selectedRoot).Select(p=>new{Path=p,Journal=RepairEngine.ReadJournal(p)}).FirstOrDefault(x=>x.Journal.Status=="Applied");if(latest==null){MessageBox.Show(this,"There is no applied repair to undo for this game.","Nothing to undo");return;}if(MessageBox.Show(this,"Undo the latest repair?\r\n\r\n"+latest.Journal.Title,"Undo last repair",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;RepairEngine.Undo(selectedRoot,latest.Path);BeginScan();}catch(Exception e){MessageBox.Show(this,e.Message,"Undo blocked");}}
    void ExportReport(){if(current==null)return;using(var s=new SaveFileDialog{Filter="Text report|*.txt",FileName="valkyrie-repair-report.txt"})if(s.ShowDialog(this)==DialogResult.OK)using(var w=new StreamWriter(s.FileName,false,System.Text.Encoding.UTF8)){w.WriteLine("Valkyrie Repair");w.WriteLine(current.Root);w.WriteLine();foreach(var f in current.Findings){w.WriteLine("["+f.Severity+"] "+f.Title);w.WriteLine(f.Details);w.WriteLine();}}}
    void RunWork(string message,Action<CancellationToken> action){if(work!=null)work.Cancel();work=new CancellationTokenSource();var token=work.Token;SetBusy(true);SetStatus(message);ShowBanner("banner-thinking.png");Task.Factory.StartNew(()=>{try{action(token);}catch(OperationCanceledException){}catch(Exception e){BeginInvoke((Action)(()=>MessageBox.Show(this,e.Message,"Valkyrie Repair")));}finally{BeginInvoke((Action)(()=>SetBusy(false)));}},token);}
    void SetBusy(bool busy){add.Enabled=!busy;find.Enabled=!busy;scan.Enabled=!busy;installs.Enabled=!busy;UseWaitCursor=busy;}
    void SetStatus(string text){status.Text=text;}
}
}
